import React from "react";
import '../style.css/Services.css';



const Services =() => {
    return(
      <main>
        <div>
          <img src="../images/banner.jpg" alt="fond violet avec un eclair blanc"></img> 
        </div>
        <div className="title"> 
          <h1>Mon offre de services</h1>
          <p>Voici les prestations sur lesquelles je peux intervenir</p>
          <hr></hr>     
        </div>
        <div>
          <h2>UX Design</h2>
          <p>L'UX Design est une discipline qui consiste à concevoir des produits (sites web, applications mobiles, logiciels, objets connectés, etc.) en plaçant l'utilisateur au centre des préoccupations.
             L'objectif est de rendre l'expérience utilisateur la plus fluide et agréable possible.</p> 
        </div>
      </main>
    );
      
    
}

export default Services;
